Here is the commit message:
pinctrl: tegra: Correctly check the supported configuration

The pincontrol registers of Tegra chips has multiple filed per
registers. There is two type of registers mux and drive. All
configurations belongs to one of these registers.

If any configurations are supported then <config>_bit is set to
bit position of these registers otherwise -1 to not support it.
The member is defined as
	s32 <config>_bit:6;

So if config is not supported ifor given SoC then it is set to -1
in soc pinmmux table.
In common driver code, to find out that given config is supported
or not, it is checked as:

s8 bit = <config>_bit;
if (bit > 31) {
	/* Not supported config */
}

But in this case, bit is s8 and hence for non supporting it is -1.

Correct the check as:
if (bit < 0) {
	/* Not supported config */
}

Fixes: e4c02dced975cb ("pinctrl: tegra: use signed bitfields for optional fields")
Signed-off-by: Laxman Dewangan <ldewangan@nvidia.com>
Acked-by: Stephen Warren <swarren@nvidia.com>
Signed-off-by: Linus Walleij <linus.walleij@linaro.org>

Here is the root cause:
The bug was caused by an incorrect conditional check in the driver code that determined whether a pin configuration was supported. The original check used a comparison that incorrectly assumed a `bit` value greater than 31 indicated an unsupported configuration, while in reality, the `bit` variable is a signed 8-bit integer. Therefore, a value of -1 (indicating unsupported configuration) was not properly recognized, leading to potential misinterpretation of configuration support.

Here is the patch:

 static int tegra_pinconf_reg(struct tegra_pmx *pmx,
 			     const struct tegra_pingroup *g,
 			     enum tegra_pinconf_param param,
 			     bool report_err,
 			     s8 *bank, s16 *reg, s8 *bit, s8 *width)
 {
 	switch (param) {
 	case TEGRA_PINCONF_PARAM_PULL:
 		*bank = g->pupd_bank;
 		*reg = g->pupd_reg;
 		*bit = g->pupd_bit;
 		*width = 2;
 		break;
 	case TEGRA_PINCONF_PARAM_TRISTATE:
 		*bank = g->tri_bank;
 		*reg = g->tri_reg;
 		*bit = g->tri_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_ENABLE_INPUT:
 		*bank = g->mux_bank;
 		*reg = g->mux_reg;
 		*bit = g->einput_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_OPEN_DRAIN:
 		*bank = g->mux_bank;
 		*reg = g->mux_reg;
 		*bit = g->odrain_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_LOCK:
 		*bank = g->mux_bank;
 		*reg = g->mux_reg;
 		*bit = g->lock_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_IORESET:
 		*bank = g->mux_bank;
 		*reg = g->mux_reg;
 		*bit = g->ioreset_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_RCV_SEL:
 		*bank = g->mux_bank;
 		*reg = g->mux_reg;
 		*bit = g->rcv_sel_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_HIGH_SPEED_MODE:
 		if (pmx->soc->hsm_in_mux) {
 			*bank = g->mux_bank;
 			*reg = g->mux_reg;
 		} else {
 			*bank = g->drv_bank;
 			*reg = g->drv_reg;
 		}
 		*bit = g->hsm_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_SCHMITT:
 		if (pmx->soc->schmitt_in_mux) {
 			*bank = g->mux_bank;
 			*reg = g->mux_reg;
 		} else {
 			*bank = g->drv_bank;
 			*reg = g->drv_reg;
 		}
 		*bit = g->schmitt_bit;
 		*width = 1;
 		break;
 	case TEGRA_PINCONF_PARAM_LOW_POWER_MODE:
 		*bank = g->drv_bank;
 		*reg = g->drv_reg;
 		*bit = g->lpmd_bit;
 		*width = 2;
 		break;
 	case TEGRA_PINCONF_PARAM_DRIVE_DOWN_STRENGTH:
 		*bank = g->drv_bank;
 		*reg = g->drv_reg;
 		*bit = g->drvdn_bit;
 		*width = g->drvdn_width;
 		break;
 	case TEGRA_PINCONF_PARAM_DRIVE_UP_STRENGTH:
 		*bank = g->drv_bank;
 		*reg = g->drv_reg;
 		*bit = g->drvup_bit;
 		*width = g->drvup_width;
 		break;
 	case TEGRA_PINCONF_PARAM_SLEW_RATE_FALLING:
 		*bank = g->drv_bank;
 		*reg = g->drv_reg;
 		*bit = g->slwf_bit;
 		*width = g->slwf_width;
 		break;
 	case TEGRA_PINCONF_PARAM_SLEW_RATE_RISING:
 		*bank = g->drv_bank;
 		*reg = g->drv_reg;
 		*bit = g->slwr_bit;
 		*width = g->slwr_width;
 		break;
 	case TEGRA_PINCONF_PARAM_DRIVE_TYPE:
 		if (pmx->soc->drvtype_in_mux) {
 			*bank = g->mux_bank;
 			*reg = g->mux_reg;
 		} else {
 			*bank = g->drv_bank;
 			*reg = g->drv_reg;
 		}
 		*bit = g->drvtype_bit;
 		*width = 2;
 		break;
 	default:
 		dev_err(pmx->dev, "Invalid config param %04x\n", param);
 		return -ENOTSUPP;
 	}

-	if (*reg < 0 || *bit > 31) {
+	if (*reg < 0 || *bit < 0)  {
 		if (report_err) {
 			const char *prop = "unknown";
 			int i;

 			for (i = 0; i < ARRAY_SIZE(cfg_params); i++) {
 				if (cfg_params[i].param == param) {
 					prop = cfg_params[i].property;
 					break;
 				}
 			}

 			dev_err(pmx->dev,
 				"Config param %04x (%s) not supported on group %s\n",
 				param, prop, g->name);
 		}
 		return -ENOTSUPP;
 	}

 	return 0;
 }



